    """Tuned Best Fit (lo=10, hi=31, penalty=19): the tightest bin wins, but leaving a gap
    strictly between 10 and 31 units costs 19. lo=0, hi=0, penalty=0 is plain Best Fit."""
    r = bins - item                                  # space left in each bin after placing the item
    return -r - 19 * ((r > 10) & (r < 31))

