    """Tuned Best Fit (lo=3, hi=7, penalty=95): the tightest bin wins, but leaving a gap
    strictly between 3 and 7 units costs 95. lo=0, hi=0, penalty=0 is plain Best Fit."""
    r = bins - item                                  # space left in each bin after placing the item
    return -r - 95 * ((r > 3) & (r < 7))

